<script setup>
import { about as wayfinderAbout1 } from './../../../actions/App/Http/Controllers/PublicController';
import { update as wayfinderUpdate2 } from './../../../actions/App/Http/Controllers/Staff/AdminPublicPageController';

import { Link, useForm } from '@inertiajs/vue3';
import StaffAdminLayout from '../../../Layouts/StaffAdminLayout.vue';

const props = defineProps({ pages: Object });
const about = useForm({ content: JSON.parse(JSON.stringify(props.pages.about)) });
const how = useForm({ content: JSON.parse(JSON.stringify(props.pages.how)) });
const faq = useForm({ content: JSON.parse(JSON.stringify(props.pages.faq)) });
function addStep() { how.content.steps.push({ number: String(how.content.steps.length + 1).padStart(2, '0'), title: '', text: '' }); }
function addFaq() { faq.content.items.push({ question: '', answer: '' }); }
</script>

<template><StaffAdminLayout><div class="admin-heading"><div><div class="eyebrow">PUBLIC WEBSITE CMS</div><h1>Public pages.</h1><p>Update the About, How it works, and FAQ pages. Changes go live when you save.</p></div><Link :href="wayfinderAbout1().url" target="_blank" class="button button-dark">Preview website <UiIcon name="arrow-up-right" :size="13"/></Link></div>
  <section class="admin-panel cms-panel"><div class="cms-head"><span class="admin-chip">ABOUT</span><h2>Our story</h2><p>Share the academy's point of view and core values.</p></div><form class="admin-form" @submit.prevent="about.put(wayfinderUpdate2.url({ pageKey: 'about' }))"><div class="admin-form-grid"><label>Eyebrow<input v-model="about.content.eyebrow"></label><label>Hero heading<input v-model="about.content.title"></label><label>Emphasized heading<input v-model="about.content.emphasis"></label><label>Intro<textarea v-model="about.content.intro" rows="2"></textarea></label><label>Section heading<input v-model="about.content.section_title"></label><label>Section support<textarea v-model="about.content.section_support" rows="2"></textarea></label></div><label>Section body<textarea v-model="about.content.section_body" rows="4"></textarea></label><div class="cms-items"><label v-for="(value,index) in about.content.values" :key="index">Value {{ index+1 }}<input v-model="about.content.values[index]"></label></div><label>Call to action heading<input v-model="about.content.cta_title"></label><div class="admin-form-actions"><button class="button button-dark" :disabled="about.processing">Save About page</button></div></form></section>
  <section class="admin-panel cms-panel"><div class="cms-head"><span class="admin-chip">HOW IT WORKS</span><h2>The learning journey</h2><p>Explain the cohort experience and what learners can expect.</p></div><form class="admin-form" @submit.prevent="how.put(wayfinderUpdate2.url({ pageKey: 'how' }))"><div class="admin-form-grid"><label>Eyebrow<input v-model="how.content.eyebrow"></label><label>Hero heading<input v-model="how.content.title"></label><label>Emphasized heading<input v-model="how.content.emphasis"></label><label>Intro<textarea v-model="how.content.intro" rows="2"></textarea></label></div><div class="cms-head step-head"><h3>Learning steps</h3><button class="admin-secondary" type="button" @click="addStep">+ Add step</button></div><div v-for="(step,index) in how.content.steps" :key="index" class="cms-repeat"><span class="cms-number">{{ step.number }}</span><div class="admin-form-grid"><label>Title<input v-model="step.title"></label><label>Description<textarea v-model="step.text" rows="2"></textarea></label></div><button v-if="how.content.steps.length > 1" class="admin-danger" type="button" @click="how.content.steps.splice(index,1)">Remove</button></div><div class="admin-form-grid"><label>Callout heading<input v-model="how.content.callout_title"></label><label>Callout body<textarea v-model="how.content.callout_body" rows="3"></textarea></label></div><div class="admin-form-actions"><button class="button button-dark" :disabled="how.processing">Save How it works page</button></div></form></section>
  <section class="admin-panel cms-panel"><div class="cms-head"><span class="admin-chip">FAQ</span><h2>Frequently asked questions</h2><p>Keep answers current so learners can make informed decisions.</p></div><form class="admin-form" @submit.prevent="faq.put(wayfinderUpdate2.url({ pageKey: 'faq' }))"><div class="admin-form-grid"><label>Eyebrow<input v-model="faq.content.eyebrow"></label><label>Hero heading<input v-model="faq.content.title"></label><label>Emphasized heading<input v-model="faq.content.emphasis"></label><label>Intro<textarea v-model="faq.content.intro" rows="2"></textarea></label></div><div class="cms-head step-head"><h3>Questions</h3><button class="admin-secondary" type="button" @click="addFaq">+ Add question</button></div><div v-for="(item,index) in faq.content.items" :key="index" class="cms-faq"><label>Question {{ index+1 }}<input v-model="item.question"></label><label>Answer<textarea v-model="item.answer" rows="3"></textarea></label><button v-if="faq.content.items.length > 1" class="admin-danger" type="button" @click="faq.content.items.splice(index,1)">Remove</button></div><div class="admin-form-actions"><button class="button button-dark" :disabled="faq.processing">Save FAQ page</button></div></form></section>
</StaffAdminLayout></template>

<style scoped>.cms-panel{margin-bottom:18px}.cms-head h2{margin:8px 0}.cms-head p{color:#777e74;font-size:12px;margin:0}.cms-head h3{font:400 1.25rem var(--serif,Georgia,serif);margin:0}.step-head{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #efeee9;padding-top:16px;margin-top:8px}.cms-items{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.cms-items label{display:grid;gap:6px;font-size:12px;color:#62695f}.cms-items input{padding:10px;border:1px solid #e2e1da;border-radius:6px}.cms-repeat{display:grid;grid-template-columns:35px minmax(0,1fr) auto;align-items:center;gap:8px;padding:13px 0;border-top:1px solid #f0efea}.cms-number{color:#6a7b61;font-size:12px}.cms-faq{display:grid;grid-template-columns:.8fr 1.2fr auto;align-items:end;gap:12px;padding:13px 0;border-top:1px solid #f0efea}.cms-faq label{display:grid;gap:6px;font-size:12px;color:#62695f}.cms-faq input,.cms-faq textarea{padding:10px;border:1px solid #e2e1da;border-radius:6px;font:inherit}.admin-secondary{background:#edf0e9;border:0;border-radius:6px;padding:8px 12px;color:#53684a;cursor:pointer}.admin-danger{border:0;background:transparent;color:#a04b44;font-size:11px;cursor:pointer}@media(max-width:700px){.cms-items{grid-template-columns:1fr}.cms-repeat,.cms-faq{grid-template-columns:1fr}.cms-number{display:none}}</style>
